SELECT DISTINCT m.* FROM sys_menu m INNER JOIN sys_role_menu rm ON rm.menu_id = m.menu_id WHERE m.status = 0 AND rm.role_id IN
#{role.value}
ORDER BY m.parent_id, m.order_num, m.menu_id

SELECT DISTINCT m.permission FROM sys_menu m INNER JOIN sys_role_menu rm ON rm.menu_id = m.menu_id WHERE m.status = 0 AND m.permission <> '' AND rm.role_id IN
#{role.value}
ORDER BY m.permission
